def _zscore(chunk: np.ndarray) -> np.ndarray:
    mean = chunk.mean(axis=-1, keepdims=True)
    std = chunk.std(axis=-1, keepdims=True)
    return ((chunk - mean) / (std + 1e-6)).astype(np.float32, copy=False)

