def _format_attribute(attr) -> str:
    """Format an attribute for display."""
    parts = [attr.type, " ", attr.name]
    if attr.keys:
        parts.append("  ")
        parts.append(",".join(attr.keys))
    if attr.comment:
        parts.append("  ")
        parts.append('"' + attr.comment + '"')
    return "".join(parts)

def _strip_comments(line: str) -> str:
    """Remove %% comments from a line, leaving %% inside quoted labels."""
    idx = _mask_quotes(line).find("%%")
    if idx >= 0:
        return line[:idx]
    return line

