def _can_place(layout: GridLayout, gc: GridCoord) -> bool:
    """Check if a 3x3 block centered at gc is free."""
    for dc in range(-1, 2):
        for dr in range(-1, 2):
            if not layout.is_free(gc.col + dc, gc.row + dr):
                return False
    return True

def _split_children(
    children: list[MindmapNode],
) -> tuple[list[MindmapNode], list[MindmapNode]]:
    """Split children into left-overflow and right groups."""
    if len(children) <= _OVERFLOW_THRESHOLD:
        return [], children
    n_left = len(children) // 3
    n_left = max(1, min(n_left, len(children) - 1))
    return children[:n_left], children[n_left:]

