    }

def _resolve_source_selection(
    engine,
    database,
    defaults: dict[str, str],
    selections: dict[str, int],
) -> tuple[str, list[str], dict, list[tuple[int, bytes]]]:
    merged = dict(defaults)
    merged.update({key: str(value) for key, value in selections.items()})
    _normalized, patchfile, patch_list, values, synth = engine._assemble(
        database, merged, defaults
    )
    inherited = set(database.patchlist_base) | set(
        database.patchlist_script
    )
    owned = [name for name in patch_list if name not in inherited]
    _file_patch, file_entries = engine.build_filelist(
        database, merged, defaults
    )
    if file_entries:
        raise AssertionError(
            f"timing/status source selection inserts files: {file_entries!r}"
        )
    writes = []
    for name in owned:
        for data_hex, raw_offset in engine.expand_entry(
            database, name, patchfile, values, synth
        ):
            for split_hex, split_offset in engine.ecc_split(
                data_hex, raw_offset
            ):
                writes.append((split_offset, bytes.fromhex(split_hex)))
    return patchfile, owned, synth, writes

def resolve_param_source_writes(
    specs: tuple[ParamFeatureSpec, ...],
    patcher_source: Path,
    patcher_data: Path,
) -> dict[tuple[str, str], tuple[int, ...]]:
    """Prove finite samples keep one exact numeric source closure/topology."""
    if not specs:
        return {}
    try:
        import tweaks_engine as engine
    except ImportError as error:
        raise RuntimeError("cannot import tools/tweaks_engine.py") from error

    src_dir = patcher_source.parent.parent
    profile_path = patcher_data.parent / "profiles" / "default.x6tweaksprofile"
    require_file(profile_path, "Tweaks default profile")
    db = engine.twr.TweaksDB(src_dir)
    base = engine.twr.load_profile(profile_path)
    inherited = set(db.patchlist_base) | set(db.patchlist_script)
    result: dict[tuple[str, str], tuple[int, ...]] = {}

    for spec in specs:
        for value in (spec.default, *spec.samples):
            merged = dict(base)
            merged[spec.source_option] = str(value)
            _normalized, patchfile, patch_list, values, synth = engine._assemble(
                db, merged, base
            )
            owned = [name for name in patch_list if name not in inherited]
            if value == spec.default:
                if owned:
                    raise AssertionError(
                        f"{spec.source_option} stock default is not a no-op: "
                        f"{owned!r}"
                    )
                continue
            if patchfile != "b01" or owned != [spec.source_option]:
                raise AssertionError(
                    f"{spec.source_option}={value} source closure changed: "
                    f"patchfile={patchfile!r}, owned={owned!r}"
                )
            if synth:
                raise AssertionError(
                    f"{spec.source_option}={value} unexpectedly synthesizes "
                    f"{sorted(synth)!r}"
                )
            _file_patch, file_entries = engine.build_filelist(db, merged, base)
            if file_entries:
                raise AssertionError(
                    f"{spec.source_option}={value} unexpectedly inserts files: "
                    f"{file_entries!r}"
                )
            writes: list[tuple[int, bytes]] = []
            for data_hex, raw_offset in engine.expand_entry(
                db, spec.source_option, patchfile, values, synth
            ):
                for split_hex, split_offset in engine.ecc_split(
                    data_hex, raw_offset
                ):
                    writes.append((split_offset, bytes.fromhex(split_hex)))
            offsets = tuple(offset for offset, _payload in writes)
            if offsets != spec.expected_raw_offsets:
                raise AssertionError(
                    f"{spec.source_option}={value} topology changed: "
                    f"{[f'0x{item:X}' for item in offsets]!r}"
                )
            expected_payloads = param_source_payloads(spec, value)
            if tuple(payload for _offset, payload in writes) != (
                expected_payloads
            ):
                raise AssertionError(
                    f"{spec.source_option}={value} is not a direct "
                    f"{spec.encoding} encoding"
                )
        result[(spec.feature_id, spec.option_id)] = (
            spec.expected_raw_offsets
        )

    for feature_id, samples in PARAM_GROUP_SAMPLES.items():
        group_specs = tuple(
            spec for spec in specs if spec.feature_id == feature_id
        )
        if not group_specs:
            continue
        by_option = {spec.option_id: spec for spec in group_specs}
        for sample in samples:
            if set(sample) != set(by_option):
                raise AssertionError(
                    f"{feature_id} group sample does not name every option"
                )
            merged = dict(base)
            expected_writes: dict[int, bytes] = {}
            expected_owned = set()
            for option_id, value in sample.items():
                spec = by_option[option_id]
                merged[spec.source_option] = str(value)
                if value == spec.default:
                    continue
                expected_owned.add(spec.source_option)
                expected_writes.update(
                    zip(
                        spec.expected_raw_offsets,
                        param_source_payloads(spec, value),
                    )
                )
            _normalized, patchfile, patch_list, values, synth = (
                engine._assemble(db, merged, base)
            )
            owned = [
                name for name in patch_list if name not in inherited
            ]
            if set(owned) != expected_owned or (
                expected_owned and patchfile != "b01"
            ) or (not expected_owned and patchfile):
                raise AssertionError(
                    f"{feature_id} group closure changed: "
                    f"patchfile={patchfile!r}, owned={owned!r}"
                )
            if synth:
                raise AssertionError(
                    f"{feature_id} group sample synthesizes "
                    f"{sorted(synth)!r}"
                )
            _file_patch, file_entries = engine.build_filelist(
                db, merged, base
            )
            if file_entries:
                raise AssertionError(
                    f"{feature_id} group sample inserts {file_entries!r}"
                )
            actual_writes: dict[int, bytes] = {}
            for name in owned:
                for data_hex, raw_offset in engine.expand_entry(
                    db, name, patchfile, values, synth
                ):
                    for split_hex, split_offset in engine.ecc_split(
                        data_hex, raw_offset
                    ):
                        actual_writes[split_offset] = bytes.fromhex(
                            split_hex
                        )
            if actual_writes != expected_writes:
                raise AssertionError(
                    f"{feature_id} group write payload changed"
                )
    return result

def semantic_write(
    stock: native.RawMode2Image,
    members: dict[int, native.IndexedMember],
    load_address: int,
    raw_offset: int,
    replacement: bytes,
) -> tuple[str, int, bytes]:
    user_offset = native.raw_to_user_offset(raw_offset)
    entry, file_offset = stock.containing_file(
        user_offset, len(replacement)
    )
    expected = native.read_iso_file_range(
        stock, entry.name, file_offset, len(replacement)
    )
    if entry.name == native.SLUS_NAME:
        return (
            "main_exe",
            load_address + file_offset - native.USER_SECTOR,
            expected,
        )
    if entry.name != "ROCK_X6.BIN":
        raise ValueError(
            f"raw source range 0x{raw_offset:X} targets unsupported "
            f"{entry.name}"
        )
    member, relative = native.containing_member(
        members, file_offset, len(replacement)
    )
    if member.payload[relative : relative + len(replacement)] != expected:
        raise AssertionError("indexed-member stock identity changed")
    disc_user = (
        stock.entries["ROCK_X6.BIN"].lba * native.USER_SECTOR
        + member.file_offset
        + relative
    )
    return "disc_user", disc_user, expected

def _radio_siblings(db):
    """{radio var: [other vars in its radio group]}. The AHK GUI auto-clears a
    radio group when one member is set (`GuiControl, Main:, radio, 1`); force()
    replicates that. Cached on db."""
    cache = getattr(db, "_radio_sib_cache", None)
    if cache is not None:
        return cache
    from collections import defaultdict
    groups = defaultdict(list)
    for c in twr.parse_gui_catalog(db.src_dir, db):
        if c.get("type") == "radio" and c.get("var") and c.get("group") is not None:
            groups[c["group"]].append(c["var"])
    cache = {}
    for members in groups.values():
        for v in members:
            cache[v] = [x for x in members if x != v]
    db._radio_sib_cache = cache
    return cache

def _hexsub(inp, padding: int = 4) -> str:
    """HexSub (filter.ahk): EndianSwap(DEC2HEX(HEX2DEC('F'*padding) - Input + 1,
    padding)) — a little-endian 'max - value' complement (used to invert a
    damage/gate scalar)."""
    top = hex2dec("F" * padding)
    return _endian_swap(_dec2hex(top - int(str(inp).strip()) + 1, padding))

