def _expected_lives_writes(value: int) -> list[tuple[int, bytes]]:
    writes = []
    if value > 9:
        writes.append((0x1D92B588, bytes(4)))
    writes.extend(
        (
            (0x1D968098, value.to_bytes(2, "little")),
            (0x1D968C90, value.to_bytes(2, "little")),
            (0x1D96808C, (value + 1).to_bytes(2, "little")),
            (0x1D968C84, (value + 1).to_bytes(2, "little")),
        )
    )
    return writes

def _state_health_groups(
    instance: InstanceProtocol,
    *,
    now: datetime,
) -> StateHealthGroupsSection:
    """Tally candidate-group counts by status plus the unresolved-backlog age span."""
    counts = {
        "pending_review": 0,
        "applying": 0,
        "resolved": 0,
        "withdrawn": 0,
    }
    ages: list[float] = []
    group_store = instance.get_group_store()
    try:
        offset = 0
        page = 500
        while True:
            batch = group_store.list_groups(limit=page, offset=offset)
            if not batch:
                break
            for group in batch:
                if group.status in counts:
                    counts[group.status] += 1
                if group.status in _UNRESOLVED_GROUP_STATUSES:
                    age = _age_seconds(group.created_at, now=now)
                    if age is not None:
                        ages.append(age)
            if len(batch) < page:
                break
            offset += page
    finally:
        group_store.close()

    return StateHealthGroupsSection(
        pending_review_count=counts["pending_review"],
        applying_count=counts["applying"],
        resolved_count=counts["resolved"],
        withdrawn_count=counts["withdrawn"],
        total_count=sum(counts.values()),
        oldest_unresolved_age_seconds=max(ages) if ages else None,
        newest_unresolved_age_seconds=min(ages) if ages else None,
    )

