def _load_trace_summaries(
    instance: InstanceProtocol,
    trace_ids: list[str],
    *,
    fallback_receipt: Receipt | None = None,
) -> list[dict[str, Any]]:
    """Load bounded trace summaries from stored traces, falling back to receipt nodes."""
    if not trace_ids:
        return _build_receipt_trace_summaries(fallback_receipt) if fallback_receipt else []

    store = instance.get_receipt_store()
    summaries: list[dict[str, Any]] = []
    try:
        for trace_id in trace_ids:
            trace = store.get_trace(trace_id)
            if trace is None:
                continue
            summaries.append(
                {
                    "trace_id": trace.trace_id,
                    "provider_name": trace.provider_name,
                    "step_id": trace.step_id,
                    "status": trace.status,
                }
            )
    finally:
        store.close()

    if summaries:
        return sorted(summaries, key=lambda item: item["trace_id"])
    return _build_receipt_trace_summaries(fallback_receipt) if fallback_receipt else []

def humanize_label(value: str) -> str:
    value = re.sub(r"(?<=[a-z])(?=[A-Z])", " ", value)
    value = value.replace("_", " ").replace("-", " ").strip()
    return value.title()

def _all_receipt_ids(store: Any) -> list[str]:
    receipt_ids: list[str] = []
    offset = 0
    while True:
        page = store.list_receipts(limit=_ENTITY_HISTORY_RECEIPT_PAGE_SIZE, offset=offset)
        if not page:
            break
        receipt_ids.extend(str(row["receipt_id"]) for row in page)
        if len(page) < _ENTITY_HISTORY_RECEIPT_PAGE_SIZE:
            break
        offset += _ENTITY_HISTORY_RECEIPT_PAGE_SIZE
    return receipt_ids

