def render_table(rows: list[dict]) -> str:
    headers = ["model", "decoder", "seconds", "wall (s)", "×realtime", "peak RAM"]
    widths  = [9, 7, 7, 9, 9, 10]

    def hline(l, m, r):
        return l + m.join("─" * (w + 2) for w in widths) + r
    def row(cells):
        parts = []
        for i, c in enumerate(cells):
            # right-align numeric columns (idx 2-5)
            parts.append(c.rjust(widths[i]) if i >= 2 else c.ljust(widths[i]))
        return "│ " + " │ ".join(parts) + " │"

    lines = [hline("┌", "┬", "┐"), row(headers), hline("├", "┼", "┤")]
    prev_dit = None
    for r in rows:
        # Visual separator when the model changes
        if prev_dit is not None and r["dit"] != prev_dit:
            lines.append(hline("├", "┼", "┤"))
        prev_dit = r["dit"]
        lines.append(row([
            r["dit"], r["decoder"], str(r["seconds"]),
            f"{r['wall_s']:.2f}",
            f"{r['realtime']:.2f}×",
            r["peak_ram"],
        ]))
    lines.append(hline("└", "┴", "┘"))
    return "\n".join(lines)

def _resolve_path(path: str) -> str:
    """Accept a .safetensors file or a PEFT adapter directory (resolve to the
    adapter_model.safetensors inside it)."""
    if os.path.isdir(path):
        cand = os.path.join(path, "adapter_model.safetensors")
        if os.path.isfile(cand):
            return cand
        hits = [f for f in os.listdir(path) if f.lower().endswith(".safetensors")]
        if len(hits) == 1:
            return os.path.join(path, hits[0])
        raise LoraError(
            f"{path!r}: expected one .safetensors adapter in the directory, found {hits}"
        )
    return path

