def _read_single_prediction_payload(output_root: Path, run_dir: Path) -> dict[str, str]:
    predictions_path = run_dir / "predictions.parquet"
    manifest_path = run_dir / "manifest.json"
    missing = [str(path) for path in (predictions_path, manifest_path) if not path.exists()]
    if missing:
        raise RuntimeError(f"remote prediction did not write required artifacts: {missing}")
    payload = {
        "relative_output_dir": str(run_dir.relative_to(output_root)),
        "predictions_b64": base64.b64encode(predictions_path.read_bytes()).decode("ascii"),
        "manifest_json": manifest_path.read_text(encoding="utf-8"),
    }
    span_set_dir = run_dir.parent
    span_set_path = span_set_dir / "span_set.parquet"
    span_manifest_path = span_set_dir / "span_set_manifest.json"
    if span_set_path.exists():
        payload["span_set_b64"] = base64.b64encode(span_set_path.read_bytes()).decode("ascii")
    if span_manifest_path.exists():
        payload["span_set_manifest_json"] = span_manifest_path.read_text(encoding="utf-8")
    return payload

def _fmt_ms(value: Any) -> str:
    float_value = _finite_float(value)
    if float_value is None:
        return "-"
    return f"{float_value * 1000.0:.0f} ms"

def iter_transformed_row(
    row: dict,
    *,
    inference_interval: float = DEFAULT_INFERENCE_INTERVAL,
    transcript_lag: float = DEFAULT_TRANSCRIPT_LAG,
    min_silence_span: float = DEFAULT_MIN_SILENCE,
    max_audio_sec: float | None = None,
) -> Iterator[dict[str, Any]]:
    array, sample_rate = decode_audio(row["audio"])
    language = _row_language(row)
    silence_spans = row["silence_spans"]
    max_audio_samples = _max_audio_samples(max_audio_sec, sample_rate=sample_rate)

    for span_index, span in enumerate(silence_spans):
        start = float(span["start"])
        end = float(span["end"])
        if end - start < min_silence_span - _EPS:
            continue
        label = "eot" if span_index == len(silence_spans) - 1 else "hold"
        for timestamp in _time_grid(start, end, inference_interval):
            end_sample = int(math.floor(float(timestamp) * sample_rate + _EPS))
            start_sample = 0
            if max_audio_samples is not None:
                start_sample = max(0, end_sample - max_audio_samples)
            yield {
                "id": row["id"],
                "language": language,
                "span_index": span_index,
                "timestamp": timestamp,
                "silence_dur": round(timestamp - start, 6),
                "label": label,
                "audio": {
                    "array": array[start_sample:end_sample].copy(),
                    "sampling_rate": sample_rate,
                },
                "messages": build_messages(row, timestamp, transcript_lag=transcript_lag),
            }

def _apply_streaming_overrides(adapter, args) -> None:
    overrides = {
        "model": getattr(args, "model", None),
        "chunk_ms": getattr(args, "chunk_ms", None),
        "eot_threshold": getattr(args, "eot_threshold", None),
    }
    for attr, value in overrides.items():
        if value is None:
            continue
        if attr == "model" and not str(value).strip():
            raise ValueError("--model must be a non-empty string.")
        if attr == "chunk_ms" and int(value) <= 0:
            raise ValueError("--chunk-ms must be positive.")
        if attr == "eot_threshold" and not 0.0 <= float(value) <= 1.0:
            raise ValueError("--eot-threshold must be in [0, 1].")
        if not hasattr(adapter, attr):
            raise TypeError(f"Adapter {adapter.adapter_id!r} does not support --{attr.replace('_', '-')}.")
        setattr(adapter, attr, value)

    if getattr(args, "skip_unsupported_languages", False) and hasattr(adapter, "skip_unsupported_languages"):
        setattr(adapter, "skip_unsupported_languages", True)

