def create_dbt_mcp_client():
    """Create the dbt MCP client with proper configuration."""
    load_dotenv()

    if not DBT_MCP_URL:
        raise ValueError("DBT_MCP_URL environment variable is required")

    return MCPClient(
        lambda: streamablehttp_client(
            url=DBT_MCP_URL,
            headers={
                "x-dbt-user-id": DBT_USER_ID,
                "x-dbt-prod-environment-id": DBT_PROD_ENV_ID,
                "x-dbt-dev-environment-id": DBT_DEV_ENV_ID,
                "x-dbt-account-id": DBT_ACCOUNT_ID,
                "Authorization": f"token {DBT_TOKEN}",
            },
        )
    )

def semantic_layer_context_mappers(
    config_provider: ConfigProvider[SemanticLayerConfig],
    client_provider: SemanticLayerClientProvider,
) -> dict[str, Callable[..., Any]]:
    async def build_context(project_id: int | None = None) -> SemanticLayerToolContext:
        config = await (
            config_provider.get_config(project_id=project_id)
            if isinstance(config_provider, ProjectConfigProvider)
            else config_provider.get_config()
        )
        return SemanticLayerToolContext(
            config_provider=StaticConfigProvider(config),
            client_provider=client_provider,
        )

    return {"context": build_context}

def parse(raw: dict[str, Any]) -> ManifestParsed:
    """Parse manifest.json using dbt-artifacts-parser (version-aware).

    Falls back to ``LenientManifest`` when strict Pydantic validation fails.
    This covers preview / unreleased dbt versions that
    emit a manifest claiming a published schema version (e.g. v12) but
    containing additional fields not yet in that schema.
    """
    try:
        return parse_manifest(manifest=raw)
    except Exception as e:
        logger.warning(
            "Strict manifest parsing failed (%s: %s); "
            "falling back to lenient dict-based parsing.  "
            "This typically occurs with dbt preview builds.",
            type(e).__name__,
            str(e)[:200],
        )
        return LenientManifest.model_validate(raw)

